function ErrorMessage({ value }: { value: unknown }) { if (!value) return null; const message = typeof value === "object" && value && "data" in value ? JSON.stringify((value as { data: unknown }).data) : "Request failed. Try again."; return <p className="form-error" role="alert">{message}</p>; }
