export function AdvertisingWorkspace({ title = "Advertising research", description = "Review provider sourced paid search metrics and connected campaign performance." }: { title?: string; description?: string }) {
  const [q, setQ] = useState(""); const { data, isLoading, error } = useAdvertisingSignalsQuery({ q: q || undefined }); const integrations = useIntegrationsQuery(); const [googleReport, reportState] = useGoogleReportMutation(); const [report, setReport] = useState<unknown>(null); const [reportError, setReportError] = useState(""); const [startDate, setStartDate] = useState(localDate(27)); const [endDate, setEndDate] = useState(localDate(1));
  const ads = integrations.data?.data.find((item) => item.id === "google-ads");
  const batches = Array.isArray(report) ? report as { results?: AdsCampaignRow[] }[] : report && typeof report === "object" && "results" in report ? [report as { results?: AdsCampaignRow[] }] : [];
  const campaigns = batches.flatMap((batch) => batch.results ?? []);
  async function loadCampaigns(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setReport(null); setReportError(""); try { const result = await googleReport({ provider: "google-ads", startDate, endDate }).unwrap(); setReport(result.data); } catch { setReportError("Google Ads report could not be loaded. Check the connected customer, API access level, and date range."); } }
  function exportCampaigns() { const rows = [["Date", "Campaign", "Channel", "Impressions", "Clicks", "Spend", "Conversions"], ...campaigns.map((row) => [row.segments?.date, row.campaign?.name, row.campaign?.advertisingChannelType, row.metrics?.impressions, row.metrics?.clicks, (Number(row.metrics?.costMicros ?? 0) / 1_000_000).toFixed(2), row.metrics?.conversions])]; const quote = (value: unknown) => "\\\"" + String(value ?? "").replaceAll("\\\"", "\\\"\\\"") + "\\\""; const csv = rows.map((line) => line.map(quote).join(",")).join("\\r\\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = "searchlight-google-ads-performance.csv"; link.click(); URL.revokeObjectURL(url); }
  return <div className="content-wrap"><div className="page-heading"><div><p className="eyebrow">PAID SEARCH / CAMPAIGN PERFORMANCE</p><h1>{title}</h1><p className="page-subtitle">{description}</p></div></div><section className="panel keyword-query-panel"><div className="panel-heading"><div><p className="eyebrow">CONNECTED ACCOUNT</p><h2>Google Ads performance</h2></div><span className="estimate-badge">{ads?.connected ? ads.account.name ?? "Connected" : "Not connected"}</span></div><form className="feature-form" onSubmit={(event) => void loadCampaigns(event)}><div className="keyword-form-row"><label>From<input type="date" value={startDate} max={endDate} onChange={(event) => setStartDate(event.target.value)}/></label><label>To<input type="date" value={endDate} min={startDate} max={localDate()} onChange={(event) => setEndDate(event.target.value)}/></label></div><button className="button button-primary" disabled={!ads?.connected || !ads.account.id || reportState.isLoading}>{reportState.isLoading ? "Loading campaign data…" : "Load campaign performance"}</button>{!ads?.connected && <p className="field-hint">Connect Google Ads and select an accessible customer in Settings. No campaign changes are made from this report.</p>}{ads?.connected && !ads.account.id && <p className="field-hint">Select a customer account in Settings before requesting a report.</p>}</form>{reportError && <p className="form-error" role="alert">{reportError}</p>}{reportState.error && <ErrorMessage value={reportState.error}/>}</section>{report !== null && <section className="panel keyword-results-panel"><div className="panel-heading"><div><p className="eyebrow">GOOGLE ADS API · FIRST-PARTY</p><h2>Campaign results <span className="count-chip">{campaigns.length}</span></h2></div><button className="button button-outline" onClick={exportCampaigns} disabled={!campaigns.length}>Export CSV</button></div>{campaigns.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Campaign</th><th>Channel</th><th>Impressions</th><th>Clicks</th><th>Spend</th><th>Conversions</th></tr></thead><tbody>{campaigns.map((row, index) => <tr key={`${row.campaign?.id ?? row.campaign?.name}-${row.segments?.date}-${index}`}><td>{row.segments?.date ?? "—"}</td><td>{row.campaign?.name ?? "—"}</td><td>{row.campaign?.advertisingChannelType ?? "—"}</td><td>{Number(row.metrics?.impressions ?? 0).toLocaleString()}</td><td>{Number(row.metrics?.clicks ?? 0).toLocaleString()}</td><td>{(Number(row.metrics?.costMicros ?? 0) / 1_000_000).toLocaleString(undefined,{style:"currency",currency:"USD"})}</td><td>{row.metrics?.conversions ?? "—"}</td></tr>)}</tbody></table></div> : <div className="keyword-empty"><strong>No campaign rows returned</strong><p>The selected customer has no reportable campaigns in this date range.</p></div>}<p className="page-footer">Google Ads reports can be delayed and are subject to Google Ads API access and quota. This workspace is read only.</p></section>}
    <section className="panel keyword-results-panel"><div className="panel-heading keyword-results-heading"><div><p className="eyebrow">KEYWORD AD SIGNALS</p><h2>Saved paid metrics <span className="count-chip">{data?.pagination.total ?? "…"}</span></h2></div><input className="table-search" aria-label="Search advertising keywords" placeholder="Filter keyword" value={q} onChange={(e) => setQ(e.target.value)}/></div>{isLoading ? <div className="panel-loading"><span className="loading-line"/></div> : error ? <ErrorMessage value={error}/> : data?.data.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Keyword</th><th>Locale</th><th>CPC</th><th>Paid competition</th><th>Source</th><th>Observed</th></tr></thead><tbody>{data.data.map((r) => <tr key={`${r.phrase}-${r.locale}`}><td>{r.phrase}</td><td>{r.locale}</td><td>{r.cpc == null ? "—" : `$${r.cpc.toFixed(2)}`}</td><td>{r.paidCompetition == null ? "—" : `${Math.round(r.paidCompetition * 100)}%`}</td><td>{r.provider} · {r.confidence.toLowerCase().replaceAll("_", " ")}</td><td>{new Date(r.observedAt).toLocaleDateString()}</td></tr>)}</tbody></table></div> : <div className="keyword-empty"><strong>No paid keyword signals saved</strong><p>Connect Google Ads or request a provider-backed keyword metrics report to populate CPC and competition records.</p></div>}</section></div>;
}

