type PageDiagnostics = { title: string; description: string; canonical: string; robots: string; h1: string[]; headings: string[]; wordCount: number; links: number; images: number; missingAlt: number; checks: { name: string; ok: boolean; detail: string }[] };
function inspectHtml(html: string): PageDiagnostics {
  const document = new DOMParser().parseFromString(html, "text/html");
  const title = document.title.trim(); const description = document.querySelector('meta[name="description" i]')?.getAttribute("content")?.trim() ?? "";
  const canonical = document.querySelector('link[rel~="canonical" i]')?.getAttribute("href") ?? ""; const robots = document.querySelector('meta[name="robots" i]')?.getAttribute("content") ?? "Not declared";
  const headings = [...document.querySelectorAll("h1,h2,h3,h4,h5,h6")].map((item) => `${item.tagName} ${item.textContent?.trim() ?? ""}`); const h1 = headings.filter((item) => item.startsWith("H1 ")).map((item) => item.slice(3));
  document.querySelectorAll("script,style,noscript,template").forEach((node) => node.remove());
  const text = document.body.textContent?.replace(/\s+/gu, " ").trim() ?? ""; const wordCount = text ? text.split(" ").length : 0;
  const images = [...document.images]; const missingAlt = images.filter((image) => !image.hasAttribute("alt")).length;
  const checks = [
    { name: "Title", ok: title.length >= 10 && title.length <= 60, detail: title ? `${title.length} characters` : "Missing title" },
    { name: "Meta description", ok: description.length >= 70 && description.length <= 160, detail: description ? `${description.length} characters` : "Missing description" },
    { name: "Single H1", ok: h1.length === 1, detail: `${h1.length} H1 elements` },
    { name: "Canonical", ok: Boolean(canonical), detail: canonical || "Not declared" },
    { name: "Indexing", ok: !/\bnoindex\b/iu.test(robots), detail: robots },
    { name: "Image alt coverage", ok: missingAlt === 0, detail: `${missingAlt} of ${images.length} images lack an alt attribute` },
  ];
  return { title, description, canonical, robots, h1, headings, wordCount, links: document.links.length, images: images.length, missingAlt, checks };
}

export function SeoquakeWorkspace() {
  const [htmlA, setHtmlA] = useState(""); const [htmlB, setHtmlB] = useState(""); const [result, setResult] = useState<{ a: PageDiagnostics; b: PageDiagnostics | null } | null>(null);
  function analyze(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setResult({ a: inspectHtml(htmlA), b: htmlB.trim() ? inspectHtml(htmlB) : null }); }
  return <div className="content-wrap"><div className="page-heading"><div><p className="eyebrow">SEO / LOCAL SOURCE ANALYSIS</p><h1>SEOquake</h1><p className="page-subtitle">Inspect page metadata and compare two HTML source snippets in your browser.</p></div></div><div className="settings-notice"><strong>Local analysis of supplied HTML</strong><p>Paste source you are authorized to inspect. The source stays in this browser page; Searchlight does not fetch the URL, contact a search engine, or show SERP overlays. These checks are heuristics, not a ranking score.</p></div><form onSubmit={analyze}><section className="panel keyword-query-panel"><div className="panel-heading"><div><p className="eyebrow">PAGE A</p><h2>Primary HTML</h2></div></div><label>Paste HTML source<textarea required value={htmlA} onChange={(event) => setHtmlA(event.target.value)} rows={12} maxLength={1000000} placeholder="Paste the page's HTML source"/></label></section><section className="panel keyword-query-panel"><div className="panel-heading"><div><p className="eyebrow">OPTIONAL COMPARISON</p><h2>Page B</h2></div></div><label>Paste a second HTML source<textarea value={htmlB} onChange={(event) => setHtmlB(event.target.value)} rows={8} maxLength={1000000} placeholder="Paste another page to compare"/></label></section><button className="button button-primary">Analyze supplied HTML</button></form>{result && <div className="feature-card-grid">{[result.a, ...(result.b ? [result.b] : [])].map((page, index) => <section className="panel keyword-results-panel" key={index}><p className="eyebrow">{index ? "PAGE B" : "PAGE A"}</p><h2>{page.title || "Untitled page"}</h2><p>{page.description || "No meta description"}</p><div className="metric-grid"><Metric label="Words" value={page.wordCount}/><Metric label="Links" value={page.links}/><Metric label="Images" value={page.images}/></div><ul className="module-feature-list">{page.checks.map((check) => <li key={check.name}><strong>{check.ok ? "âœ“" : "Review"} Â· {check.name}</strong><small>{check.detail}</small></li>)}</ul><p>Canonical: {page.canonical || "Not declared"}</p><p>H1: {page.h1.join(" Â· ") || "Missing"}</p><details><summary>Heading outline</summary><ol>{page.headings.map((heading, i) => <li key={`${heading}-${i}`}>{heading}</li>)}</ol></details></section>)}</div>}</div>;
}
