export function ManualObservationPanel({ module }: { module: ManualObservationModule }) {
  const config = observationConfigs[module]; const [q, setQ] = useState(""); const { data, isLoading, error } = useManualResearchQuery({ module, q: q || undefined }); const [create, createState] = useCreateManualResearchMutation(); const [update] = useUpdateManualResearchMutation(); const [notice, setNotice] = useState(""); const rows = data?.data ?? [];
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const values = new FormData(form); const body: Record<string, unknown> = {}; for (const field of config.fields) { const value = String(values.get(field.name) ?? "").trim(); if (!value) continue; body[field.name] = field.type === "number" ? Number(value) : field.type === "date" ? new Date(`${value}T12:00:00.000Z`).toISOString() : value; } if ((module === "ranking-observations") && !String(values.get("position") ?? "").trim()) body.position = null; try { const saved = await create({ module, values: body }).unwrap(); form.reset(); setNotice(saved.note); } catch { setNotice("Could not save the observation. Check the source, URLs, date, and numeric fields."); } }
  function summary(record: ManualResearchRecord) { const s = record.settings; switch (module) { case "keyword-observations": return `${s.phrase} Â· ${s.country} Â· volume ${s.searchVolume ?? "â€”"} Â· ${s.source}`; case "competitor-observations": return `${s.domain} Â· ${s.country} Â· ${s.overlappingKeywords ?? "â€”"} overlapping keywords Â· ${s.source}`; case "backlink-observations": return `${s.sourceDomain} â†’ ${s.targetUrl} Â· ${s.linkType} Â· ${s.source}`; case "ranking-observations": return `${s.phrase} Â· ${s.country}/${s.device} Â· ${s.position == null ? "not found" : `#${s.position}`} Â· ${s.source}`; } }
  function exportCsv() { const quote = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`; const columns = config.fields.map((field) => field.name); const lines = [[...columns, "record_status", "created_at"], ...rows.map((row) => [...columns.map((column) => row.settings[column]), row.status, row.createdAt])]; const url = URL.createObjectURL(new Blob([lines.map((line) => line.map(quote).join(",")).join("\r\n")], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${module}.csv`; anchor.click(); URL.revokeObjectURL(url); }
  return <section className="panel keyword-query-panel"><div className="panel-heading"><div><p className="eyebrow">MANUAL / SOURCE-LINKED EVIDENCE</p><h2>{config.title}</h2><p className="page-subtitle">These records remain separate from provider observations and are labeled manual.</p></div></div><form className="feature-form" onSubmit={(event) => void submit(event)}>{config.fields.map((field) => <label key={field.name}>{field.label}{field.options ? <select name={field.name} required={field.required}><option value="">Chooseâ€¦</option>{field.options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : field.name === "anchorText" ? <textarea name={field.name} rows={2} maxLength={500}/> : <input name={field.name} type={field.type === "date" ? "date" : field.type === "number" ? "number" : field.name.toLowerCase().includes("url") ? "url" : "text"} min={field.type === "number" ? "0" : undefined} max={field.name === "difficulty" || field.name === "paidCompetition" ? field.name === "difficulty" ? "100" : "1" : undefined} step={field.type === "number" ? "any" : undefined} required={field.required} maxLength={field.type === "number" || field.type === "date" ? undefined : 300}/>}</label>)}<button className="button button-primary" disabled={createState.isLoading}>{createState.isLoading ? "Savingâ€¦" : "Save observation"}</button></form>{notice && <p role="status">{notice}</p>}<div className="settings-notice"><strong>Manual data only</strong><p>No licensed index is queried. Source and date are retained with each record so users can verify it independently.</p></div><div className="panel-heading keyword-results-heading"><div><p className="eyebrow">SAVED RECORDS</p><h3>{rows.length} observations</h3></div><div className="results-controls"><input className="table-search" aria-label="Search manual observations" value={q} onChange={(event) => setQ(event.target.value)} placeholder="Filter saved evidence"/><button className="button button-outline" onClick={exportCsv} disabled={!rows.length}>Export CSV</button></div></div>{isLoading ? <p>Loading saved observationsâ€¦</p> : error ? <p role="alert">Could not load observations.</p> : rows.length ? <ul className="module-feature-list">{rows.slice(0, 25).map((row) => <li key={row.id}><span><strong>{summary(row)}</strong><small>{row.settings.observedAt ? new Date(String(row.settings.observedAt)).toLocaleDateString() : new Date(row.createdAt).toLocaleDateString()} Â· {row.status}</small></span>{row.status !== "archived" && <button className="button button-outline" onClick={() => void update({ module, id: row.id, status: "archived" })}>Archive</button>}</li>)}</ul> : <p className="keyword-empty">No manual observations saved yet.</p>}</section>;
}

